import { Component, inject, OnInit } from '@angular/core';
import { TramiteService } from '../../../controllers/tramite.service';
import { TramiteTipo } from '../../../models/tramite';
import { Router } from '@angular/router';
import { filter, firstValueFrom } from 'rxjs';
import { VanillaDialogService } from '../../../services/vanilla-dialog/vanilla-dialog.service';

@Component({
  selector: 'app-seleccionar-tramite',
  imports: [],
  templateUrl: './seleccionar-tramite.html',
  styleUrl: './seleccionar-tramite.css',
})
export class SeleccionarTramite implements OnInit {
  private router = inject(Router);
  private dialog = inject(VanillaDialogService)
  private tramiteController = inject(TramiteService);

  yaTieneTramite = false;
  loading = true;

  async ngOnInit() {
    this.yaTieneTramite = await this.tramiteController.usuarioLogeadoTieneTramite();
    this.loading = false;
  }

  public async crearTramite(tipo: TramiteTipo) {
    if (this.yaTieneTramite) {
      return;
    }

    const confirmation = await firstValueFrom(this.dialog.show({
      title: '¿Estás seguro?',
      body: '¿Está seguro de que deseas iniciar este tramite? Una vez iniciado, no podrás cambiar el tipo de trámite.',
      respNo: 'Cancelar',
      respYes: 'Iniciar',
      tipo: 'info'
    }).pipe(filter(data => !!data)))

    if(!confirmation?.closedByAgree){
      return;
    }

    const res = await this.tramiteController.new({
      tipo: tipo
    });

    if (res) {
      this.router.navigate(['/main/externos/mi-empresa']);
    }
  }
}
